mapper.select:
SELECT AS time_bucket, r.channel_id, MAX(c.channel_name) AS channel_name, r.monitor_id, MAX(m.monitor_name) AS monitor_name, r.advertiser_id, MAX(a.advertiser_name) AS advertiser_name, r.app_link_id, MAX(l.link_name) AS app_link_name, COALESCE(MAX(d.ratio), 1.0000) AS deduction_ratio, SUM(r.impressions) AS impressions, SUM(r.clicks) AS clicks, SUM(r.eligible_click_count) AS eligible_click_count, SUM(r.deduplicated_click_count) AS deduplicated_click_count, SUM(r.skipped_click_count) AS skipped_click_count, SUM(r.classified_click_count) AS classified_click_count, CASE WHEN SUM(r.impressions) = 0 THEN 0 ELSE ROUND(SUM(r.clicks) * 100.0 / SUM(r.impressions), 4) END AS click_rate, SUM(r.cost_amount) AS cost_amount, SUM(r.revenue_amount) AS revenue_amount, SUM(r.activate_count) AS activate_count, CASE WHEN SUM(r.classified_click_count) != SUM(r.clicks) OR SUM(r.eligible_click_count) = 0 THEN NULL ELSE ROUND(SUM(r.activate_count) * 100.0 / SUM(r.eligible_click_count), 4) END AS activate_rate, SUM(r.first_activate_count) AS first_activate_count, CASE WHEN SUM(r.classified_click_count) != SUM(r.clicks) OR SUM(r.eligible_click_count) = 0 THEN NULL ELSE ROUND(SUM(r.first_activate_count) * 100.0 / SUM(r.eligible_click_count), 4) END AS first_activate_rate, SUM(r.evoke_count) AS evoke_count, SUM(r.reactivation_count) AS reactivation_count, CASE WHEN SUM(r.classified_click_count) != SUM(r.clicks) OR SUM(r.eligible_click_count) = 0 THEN NULL ELSE ROUND(SUM(r.reactivation_count) * 100.0 / SUM(r.eligible_click_count), 4) END AS reactivation_rate, SUM(r.login_count) AS login_count, SUM(r.register_count) AS register_count, SUM(r.payment_count) AS payment_count, SUM(r.acquisition_count) AS acquisition_count, SUM(r.next_stay_count) AS next_stay_count, SUM(r.retention_3d_count) AS retention_3d_count, SUM(r.retention_4d_count) AS retention_4d_count, SUM(r.retention_5d_count) AS retention_5d_count, SUM(r.retention_6d_count) AS retention_6d_count, SUM(r.retention_7d_count) AS retention_7d_count, SUM(r.visit_count) AS visit_count, SUM(r.authentication_count) AS authentication_count, SUM(r.order_count) AS order_count, SUM(r.first_order_count) AS first_order_count, SUM(r.finish_order_count) AS finish_order_count, SUM(r.raw_conversion_count) AS raw_conversion_count, SUM(r.forwarded_conversion_count) AS forwarded_conversion_count, SUM(r.deducted_conversion_count) AS deducted_conversion_count, SUM(r.delivery_failure_count) AS delivery_failure_count FROM scx_adx_hourly_report r LEFT JOIN scx_adx_channel c ON c.id = r.channel_id AND c.deleted = 0 LEFT JOIN scx_adx_monitor_link m ON m.id = r.monitor_id AND m.deleted = 0 LEFT JOIN scx_adx_advertiser a ON a.id = r.advertiser_id AND a.deleted = 0 LEFT JOIN scx_adx_app_link l ON l.id = r.app_link_id AND l.deleted = 0 LEFT JOIN scx_adx_deduction_rule d ON d.channel_id = r.channel_id AND d.app_link_id = r.app_link_id AND d.deleted = 0 WHERE r.time_hour >= #{start} AND r.time_hour < #{end} AND r.channel_id = #{channelId} AND r.monitor_id = #{monitorId} AND r.advertiser_id = #{advertiserId} AND r.app_link_id = #{appLinkId}
AND r.advertiser_id IN #{id}
AND 1=0
AND r.channel_id IN #{id}
AND 1=0
GROUP BY , r.channel_id, r.monitor_id, r.advertiser_id, r.app_link_id ORDER BY DESC, MAX(c.channel_name), MAX(a.advertiser_name)

SELECT
  (SELECT COALESCE(SUM(a.balance),0) FROM scx_adx_advertiser a
   WHERE a.deleted=0
   AND a.id = #{advertiserId}


       AND a.id IN
       #{id}

     AND 1=0

  ) AS totalBalance,
  COALESCE(SUM(CASE WHEN b.mode='RECHARGE' AND b.status='POSTED' THEN b.amount ELSE 0 END),0) AS rechargeAmount,
  COALESCE(SUM(CASE WHEN b.mode='CPC' AND b.status='POSTED' THEN b.amount ELSE 0 END),0) AS cpcSpend,
  COALESCE(SUM(CASE WHEN b.mode='CPA' AND b.status='POSTED' THEN b.amount ELSE 0 END),0) AS cpaSpend,
  SUM(b.mode='CPC' AND b.status='REJECTED') AS rejectedCharges,
  SUM(b.mode='CPA' AND b.status='REJECTED') AS cpaRejectedCharges
FROM scx_ocpx_billing_entry b
WHERE b.create_time >= #{start} AND b.create_time < #{end}
AND b.debug_execution_id IS NULL
AND b.advertiser_id = #{advertiserId}


    AND b.advertiser_id IN
    #{id}

  AND 1=0



    AND (b.mode='RECHARGE' OR b.channel_id IN
    #{id})

  AND b.mode='RECHARGE'

AND (b.mode='RECHARGE' OR (b.mode='CPA' AND b.status='REJECTED'
  AND b.channel_id = #{channelId}
  AND b.app_link_id = #{appLinkId}
  AND b.monitor_id = #{monitorId}
) OR EXISTS (
  SELECT 1 FROM scx_ocpx_event e WHERE e.event_id=b.charge_event_id AND e.is_debug=0
  AND e.channel_id = #{channelId}
  AND e.app_link_id = #{appLinkId}
  AND e.monitor_id = #{monitorId}
))
